@implementation MTRBaseClusterTimeSynchronization

- (instancetype)initWithDevice:(MTRBaseDevice *)device endpointID:(NSNumber *)endpointID queue:(dispatch_queue_t)queue
{
    if (self = [super initWithEndpointID:endpointID queue:queue]) {
        if (device == nil) {
            return nil;
        }

        _device = device;
    }
    return self;
}

- (void)setUTCTimeWithParams:(MTRTimeSynchronizationClusterSetUTCTimeParams *)params completion:(MTRStatusCompletion)completion
{
    if (params == nil) {
        params = [[MTRTimeSynchronizationClusterSetUTCTimeParams
            alloc] init];
    }

    auto responseHandler = ^(id _Nullable response, NSError * _Nullable error) {
        completion(error);
    };

    auto * timedInvokeTimeoutMs = params.timedInvokeTimeoutMs;

    using RequestType = TimeSynchronization::Commands::SetUTCTime::Type;
    [self.device _invokeKnownCommandWithEndpointID:@(self.endpoint)
                                         clusterID:@(RequestType::GetClusterId())
                                         commandID:@(RequestType::GetCommandId())
                                    commandPayload:params
                                timedInvokeTimeout:timedInvokeTimeoutMs
                       serverSideProcessingTimeout:params.serverSideProcessingTimeout
                                     responseClass:nil
                                             queue:self.callbackQueue
                                        completion:responseHandler];
}
