@implementation MTRBaseClusterThermostat

- (instancetype)initWithDevice:(MTRBaseDevice *)device endpointID:(NSNumber *)endpointID queue:(dispatch_queue_t)queue
{
    if (self = [super initWithEndpointID:endpointID queue:queue]) {
        if (device == nil) {
            return nil;
        }

        _device = device;
    }
    return self;
}

- (void)setpointRaiseLowerWithParams:(MTRThermostatClusterSetpointRaiseLowerParams *)params completion:(MTRStatusCompletion)completion
{
    if (params == nil) {
        params = [[MTRThermostatClusterSetpointRaiseLowerParams
            alloc] init];
    }

    auto responseHandler = ^(id _Nullable response, NSError * _Nullable error) {
        completion(error);
